window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ef2ec717f02714dd"]={"versions": [{"id": "FIG-ef2ec717f02714dd", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR ECU Configuration Parameter Definition (ECUC) innerhalb der Spezifikation der AUTOSAR Runtime Environment (SWS RTE). Das Diagramm beschreibt die Struktur der BSW-Parameterdefinition für die Interaktion der RTE mit dem AUTOSAR Betriebssystem (OS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RteOsInteraction</strong> (<code>EcucParamConfContainerDef</code>): Zentraler Container zur BSW-Parameterdefinition der RTE/OS-Interaktion mit Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>RteUsedOsActivation</strong> (<code>EcucParamConfContainerDef</code>): Sub-Container zur Spezifikation der durch die RTE genutzten OS-Aktivierungsmechanismen. Kardinalität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>RteModeToScheduleTableMapping</strong> (<code>EcucParamConfContainerDef</code>): Sub-Container zur Definition der Abbildung von RTE-Modi auf OS-Schedule-Tables. Kardinalität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>Beziehungen</strong>: Komposition (<code>+subContainer</code>) vom Hauptcontainer <code>RteOsInteraction</code> zu den beiden Sub-Containern <code>RteUsedOsActivation</code> und <code>RteModeToScheduleTableMapping</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell der Konfigurationsstruktur; kein dynamischer Laufzeitablauf dargestellt. Beschreibt die Konfigurationsdatenbasis für Generatoren zur Erzeugung der RTE-zu-OS-Aufrufe (Task-Aktivierung, Event-Setting) und Modus-getriebener Schedule-Table-Steuerung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Vorgabe für AUTOSAR-Konfigurationstools und den RTE-Generator. Mindestens eine Instanz von <code>RteOsInteraction</code> ist im ECUC-Modell verpflichtend (<code>1..*</code>). Die Sub-Container <code>RteUsedOsActivation</code> und <code>RteModeToScheduleTableMapping</code> sind optional (<code>0..*</code>) und werden bedarfsabhängig projektiert, wenn OS-Taskaktivierungen oder Modus-Umschaltungen auf OS-Schedule-Tables abgebildet werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ab1ca67d9dd814b9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR ECU Configuration Parameter Definition (ECUC) innerhalb der Spezifikation der AUTOSAR Runtime Environment (SWS RTE). Das Diagramm beschreibt die Struktur der BSW-Parameterdefinition für die Interaktion der RTE mit dem AUTOSAR Betriebssystem (OS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RteOsInteraction</strong> (<code>EcucParamConfContainerDef</code>): Zentraler Container zur BSW-Parameterdefinition der RTE/OS-Interaktion mit Kardinalität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>RteUsedOsActivation</strong> (<code>EcucParamConfContainerDef</code>): Sub-Container zur Spezifikation der durch die RTE genutzten OS-Aktivierungsmechanismen. Kardinalität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>RteModeToScheduleTableMapping</strong> (<code>EcucParamConfContainerDef</code>): Sub-Container zur Definition der Abbildung von RTE-Modi auf OS-Schedule-Tables. Kardinalität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><strong>Beziehungen</strong>: Komposition (<code>+subContainer</code>) vom Hauptcontainer <code>RteOsInteraction</code> zu den beiden Sub-Containern <code>RteUsedOsActivation</code> und <code>RteModeToScheduleTableMapping</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell der Konfigurationsstruktur; kein dynamischer Laufzeitablauf dargestellt. Beschreibt die Konfigurationsdatenbasis für Generatoren zur Erzeugung der RTE-zu-OS-Aufrufe (Task-Aktivierung, Event-Setting) und Modus-getriebener Schedule-Table-Steuerung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Vorgabe für AUTOSAR-Konfigurationstools und den RTE-Generator. Mindestens eine Instanz von <code>RteOsInteraction</code> ist im ECUC-Modell verpflichtend (<code>1..*</code>). Die Sub-Container <code>RteUsedOsActivation</code> und <code>RteModeToScheduleTableMapping</code> sind optional (<code>0..*</code>) und werden bedarfsabhängig projektiert, wenn OS-Taskaktivierungen oder Modus-Umschaltungen auf OS-Schedule-Tables abgebildet werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ef2ec717f02714dd", "to": "FIG-ab1ca67d9dd814b9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
